INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Hat eine IPv4-Adresse immer 4 Oktette?', 2, '[{"text": "Ja", "correct": true, "because": "Standardformat von IPv4"}, {"text": "Nein", "correct": false, "because": "Keine Abweichung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Wert ist das Maximum für ein Oktett?', 3, '[{"text": "255", "correct": true, "because": "8 Bits erlauben 0-255"}, {"text": "127", "correct": false, "because": "Nur halber Bereich"}, {"text": "256", "correct": false, "because": "Obergrenze überschritten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Oktett geht von 0-255. b) IPv4 hat 5 Oktette.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IPv4 hat 4 Oktette"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Dezimaldarstellung?', 4, '[{"text": "Oktettanzahl", "correct": false, "because": "Definiert die Struktur"}, {"text": "Wertebereich", "correct": false, "because": "Bestimmt Gültigkeit"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 255.255.255.255 eine gültige Adresse ist?', 2, '[{"text": "Ja", "correct": true, "because": "Broadcast-Adresse"}, {"text": "Nein", "correct": false, "because": "Passt ins Format"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse steht für ein lokales Netzwerk?', 3, '[{"text": "192.168.0.0", "correct": true, "because": "Privater Bereich"}, {"text": "256.1.2.3", "correct": false, "because": "Ungültig über 255"}, {"text": "127.0.0.0", "correct": false, "because": "Loopback"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Dezimaldarstellung?', 5, '[{"text": "4 Oktette", "correct": true, "because": "Feste Struktur"}, {"text": "0-255 pro Oktett", "correct": true, "because": "Bitbereich"}, {"text": "Hexadezimal", "correct": false, "because": "IPv6-spezifisch"}, {"text": "5 Oktette", "correct": false, "because": "IPv4 hat 4"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) IPv4 hat 4 Oktette. b) Werte gehen bis 999. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Maximal 255 pro Oktett"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Dezimaldarstellung?', 4, '[{"text": "Punkttrennung", "correct": false, "because": "Trennt Oktette"}, {"text": "Wertebereich", "correct": false, "because": "Definiert Gültigkeit"}, {"text": "Binärcode", "correct": true, "because": "Nur intern relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 0.0.0.0 eine spezielle Adresse?', 2, '[{"text": "Ja", "correct": true, "because": "Default-Route oder unbekannt"}, {"text": "Nein", "correct": false, "because": "Hat Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich ist für ein Oktett ungültig?', 4, '[{"text": "0-255", "correct": false, "because": "Gültiger Bereich"}, {"text": "256-300", "correct": true, "because": "Überschreitet 8 Bits"}, {"text": "1-254", "correct": false, "because": "Teilmenge, aber gültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 127.0.0.1 nur lokal genutzt wird. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Loopback-Adresse"}, {"text": "Nein", "correct": false, "because": "Spezielle Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Adressvergabe?', 3, '[{"text": "Korrekte Werte", "correct": true, "because": "Sichert Gültigkeit"}, {"text": "Schnelle Eingabe", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 4 Oktette sind Standard. b) Werte über 255 sind erlaubt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) überschreitet Bits"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Dezimaldarstellung?', 5, '[{"text": "Lesbarkeit", "correct": true, "because": "Einfacher als Binär"}, {"text": "Kompaktheit", "correct": true, "because": "4 Zahlen statt 32 Bits"}, {"text": "Schnellere Berechnung", "correct": false, "because": "Binär ist präziser"}, {"text": "Unendliche Werte", "correct": false, "because": "Begrenzt auf 255"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Darstellung unwichtig?', 3, '[{"text": "Oktettanzahl", "correct": false, "because": "Definiert Struktur"}, {"text": "Punkttrennung", "correct": false, "because": "Trennt Werte"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 10.0.0.1 eine private Adresse?', 3, '[{"text": "Ja", "correct": true, "because": "Im privaten Bereich 10.0.0.0"}, {"text": "Nein", "correct": false, "because": "Falsche Einordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 172.16.0.0 öffentlich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Privater Bereich 172.16-31"}, {"text": "Ja", "correct": false, "because": "Nicht öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse ist ungültig?', 4, '[{"text": "192.168.1.1", "correct": false, "because": "Gültig im Bereich"}, {"text": "300.1.2.3", "correct": true, "because": "Überschreitet 255"}, {"text": "10.0.0.255", "correct": false, "because": "Gültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat 255.255.255.255?', 3, '[{"text": "Broadcast", "correct": true, "because": "Sendet an alle im Netz"}, {"text": "Loopback", "correct": false, "because": "Das ist 127.0.0.1"}, {"text": "Gateway", "correct": false, "because": "Spezifische Adresse"}]');
